<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    ./scripts/rebuild.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # runs once for the whole batch</span></span>
